function main(input) {
  const quantity = Math.max(0, input.inputs.target - input.evidence.available);
  return { quantity, tooLarge: quantity > 500 };
}

function main(input, luma) {
  const days = Math.floor((Date.parse(luma.now) - Date.parse(input.evidence.promisedAt)) / 86400000);
  return { daysLate: Math.max(0, days), late: days > 0 };
}

function main(input) {
  const margin = input.inputs.price > 0 ? ((input.inputs.price - input.inputs.cost) / input.inputs.price) * 100 : 0;
  return { margin, belowFloor: margin < 15 };
}
